import time
from functools import wraps

def retry_decorator(n, delay):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(n):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    time.sleep(delay)
            raise e
        return wrapper
    return decorator

def slugify_title(title):
